// Edit only these two values. One product per manual starter execution.
const asin = 'REPLACE_WITH_ASIN';
const amazonDomain = 'amazon.com';
if (!/^[A-Z0-9]{10}$/.test(asin)) throw new Error('Set one uppercase 10-character ASIN before running.');
if (amazonDomain !== 'amazon.com') throw new Error('This starter uses amazon.com; review the contract before changing markets.');
return [{json: {asins: asin, amazonDomain}}];

const body = $input.first().json;
const request = $('Product input').first().json;
if (typeof body.code !== 'number' || body.code !== 0) throw new Error('API business error: inspect the HTTP node output. Do not automatically rerun.');
if (!body.data || !Array.isArray(body.data.products)) throw new Error('No data.products array: inspect the raw output for a task identifier or schema change.');
if (body.data.products.length !== 1) throw new Error('Expected exactly one returned product; inspect the raw output.');
const product = body.data.products[0];
if (!product || product.asin !== request.asins) throw new Error('Returned ASIN does not match the requested ASIN.');
if (product.statusCode != null && product.statusCode !== 200) throw new Error('Product record reports an error; no row written.');
const fields = ['title', 'brand', 'price', 'currency', 'rating', 'ratings', 'stock'];
const missingFields = fields.filter(k => product[k] == null);
const cell = value => {
  if (value == null) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  if (typeof value === 'string' && (/^[\t\r\n]/.test(value) || /^[=+\-@]/.test(value.trimStart()))) return "'" + value;
  return value;
};
const row = {asin: product.asin, requested_domain: request.amazonDomain};
for (const field of fields) row[field] = cell(product[field]);
row.missing_fields = missingFields.join(';');
row.observed_at_utc = new Date().toISOString();
row.execution_id = String($execution.id);
return [{json: row}];
